import json, os, glob

sessions = sorted(glob.glob('.state/sessions/history/s_177410*/session.jsonl') + 
                  glob.glob('.state/sessions/history/s_177411*/session.jsonl'), 
                  key=os.path.getmtime, reverse=True)[:35]

error_patterns = ['P53', 'P98', 'ENOENT', 'oldText not found', 'not found in file', 
                  'PIVOT REQUIRED', 'Error:', 'Permission denied', 'command not found',
                  'No such file', 'edit-match-fail']

errors_found = []
wasted_reads = {}  # (agent, sid) -> {path: count}

for sjl in sessions:
    sid = sjl.split('/')[-3]
    meta_path = sjl.replace('session.jsonl', 'meta.json')
    try:
        with open(meta_path) as f:
            agent = json.load(f).get('agent','?')
    except:
        agent = '?'

    try:
        with open(sjl) as f:
            messages = [json.loads(l) for l in f]
    except:
        continue

    read_paths = {}  # path -> count for this session

    for msg in messages:
        content = msg.get('content', [])
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict):
                continue

            # Check toolCall for read paths
            if block.get('type') == 'toolCall' and block.get('name') == 'read':
                args = str(block.get('arguments', ''))
                # extract path
                import re
                path_match = re.search(r\"'path':\s*'([^']+)'\", args)
                if not path_match:
                    path_match = re.search(r'\"path\":\s*\"([^\"]+)\"', args)
                if path_match:
                    p = path_match.group(1)
                    read_paths[p] = read_paths.get(p, 0) + 1

            # Check toolResult content for error patterns
            if block.get('type') == 'toolResult':
                text = str(block.get('text', block.get('content', '')))[:500]
                for pattern in error_patterns:
                    if pattern in text:
                        errors_found.append((sid, agent, pattern, text[:150]))
                        break

    # Track duplicate reads
    for path, count in read_paths.items():
        if count > 2:
            if (agent, sid) not in wasted_reads:
                wasted_reads[(agent, sid)] = {}
            wasted_reads[(agent, sid)][path] = count

print('=== ERROR PATTERNS IN TOOL RESULTS ===')
for sid, agent, pattern, text in errors_found[:30]:
    print(f'  {agent:12s} | {pattern:20s} | {text[:100]}')

print(f'\n=== DUPLICATE READS (same file >2x in session) ===')
for (agent, sid), paths in wasted_reads.items():
    for path, count in paths.items():
        print(f'  {agent:12s} | {count}x | {path} | {sid}')
