python3 -c "
import json, os, glob, re
from collections import defaultdict

current = 1774116569726
cutoff = current - 10 * 3600 * 1000

# Analyze all sessions in last 10h for tool quality issues
tool_errors = []  # (agent, sid, tool, error_type, detail)
duplicate_reads = defaultdict(lambda: defaultdict(int))  # (agent, sid) -> {path: count}
wrong_tool = []  # cases where bash was used for read or vice versa
large_results = []  # tool results > 20KB

all_dirs = glob.glob('.state/sessions/history/s_*/')
analyzed = 0

for d in all_dirs:
    meta_path = os.path.join(d, 'meta.json')
    sjl_path = os.path.join(d, 'session.jsonl')
    if not os.path.exists(meta_path) or not os.path.exists(sjl_path):
        continue
    try:
        with open(meta_path) as f:
            m = json.load(f)
        if m.get('startedAt', 0) < cutoff:
            continue
        agent = m.get('agent', '?')
        sid = os.path.basename(d.rstrip('/'))
    except:
        continue

    try:
        with open(sjl_path) as f:
            messages = [json.loads(l) for l in f]
    except:
        continue

    analyzed += 1

    # Track reads per session
    read_paths = defaultdict(int)
    last_call_ids = {}  # id -> (name, args_str)

    for msg in messages:
        content = msg.get('content', [])
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict):
                continue

            if block.get('type') == 'toolCall':
                name = block.get('name', '?')
                args_str = str(block.get('arguments', ''))
                call_id = block.get('id', '')
                last_call_ids[call_id] = (name, args_str)

                # Track reads
                if name == 'read':
                    path_m = re.search(r\"'path':\s*'([^']+)'\", args_str) or re.search(r'\"path\":\s*\"([^\"]+)\"', args_str)
                    if path_m:
                        read_paths[path_m.group(1)] += 1

                # Detect bash-for-read: bash(cat file) when they should use read()
                if name == 'bash':
                    cmd_m = re.search(r\"'command':\s*'([^']*?)'\", args_str) or re.search(r'\"command\":\s*\"([^\"]*?)\"', args_str)
                    if cmd_m:
                        cmd = cmd_m.group(1)
                        # Cat-only commands that should be read()
                        if re.match(r'^cat\s+[\w/._-]+\s*$', cmd):
                            wrong_tool.append((agent, sid, 'bash-as-read', cmd[:80]))

            elif block.get('type') == 'toolResult':
                text = str(block.get('text', ''))
                call_id = block.get('toolCallId', '')

                # Check for large results
                if len(text) > 20000:
                    tool_name = last_call_ids.get(call_id, ('?',''))[0]
                    large_results.append((agent, sid, tool_name, len(text)))

                # Check for error indicators
                if any(p in text[:500] for p in ['P53 Violation', 'P98 ', 'ENOENT', 'No such file', 'Permission denied']):
                    tool_name = last_call_ids.get(call_id, ('?',''))[0]
                    error_type = 'P53' if 'P53' in text[:200] else 'P98' if 'P98' in text[:200] else 'ENOENT' if 'ENOENT' in text[:500] or 'No such file' in text[:500] else 'permission'
                    tool_errors.append((agent, sid, tool_name, error_type, text[:150]))

                if 'oldText not found' in text[:500] or 'not found in file' in text[:500]:
                    tool_name = last_call_ids.get(call_id, ('?',''))[0]
                    tool_errors.append((agent, sid, tool_name, 'edit-match-fail', text[:150]))

                if 'PIVOT REQUIRED' in text[:500]:
                    tool_name = last_call_ids.get(call_id, ('?',''))[0]
                    tool_errors.append((agent, sid, tool_name, 'pivot-required', text[:150]))

    # Record duplicate reads
    for path, count in read_paths.items():
        if count > 1:
            duplicate_reads[(agent, sid)][path] = count

print(f'Analyzed {analyzed} sessions')

print(f'\n=== TOOL ERRORS ({len(tool_errors)}) ===')
error_by_type = defaultdict(int)
error_by_agent = defaultdict(int)
for agent, sid, tool, etype, detail in tool_errors:
    error_by_type[etype] += 1
    error_by_agent[agent] += 1

print('By type:')
for etype, count in sorted(error_by_type.items(), key=lambda x: -x[1]):
    print(f'  {etype}: {count}')
print('By agent:')
for agent, count in sorted(error_by_agent.items(), key=lambda x: -x[1]):
    print(f'  {agent}: {count}')
print('Details:')
for agent, sid, tool, etype, detail in tool_errors[:15]:
    print(f'  {agent:12s} | {tool:8s} | {etype:16s} | {detail[:100]}')

print(f'\n=== DUPLICATE READS (same file >1x in session) ===')
dup_count = 0
for (agent, sid), paths in sorted(duplicate_reads.items()):
    for path, count in sorted(paths.items(), key=lambda x: -x[1]):
        if count > 2:
            print(f'  {agent:12s} | {count}x | {path[:70]} | {sid}')
            dup_count += 1
print(f'Total duplicate-read incidents (>2x): {dup_count}')

print(f'\n=== WRONG TOOL USAGE (bash as cat) ({len(wrong_tool)}) ===')
for agent, sid, issue, detail in wrong_tool[:10]:
    print(f'  {agent:12s} | {issue} | {detail}')

print(f'\n=== LARGE TOOL RESULTS (>20KB) ({len(large_results)}) ===')
for agent, sid, tool, size in sorted(large_results, key=lambda x: -x[3])[:15]:
    print(f'  {agent:12s} | {tool:8s} | {size//1024:4d}KB | {sid}')
